import re


def find_index_of_last_rrc_connection_request_message(messages):
    """
    find_index_of_last_rrc_connection_request_message
    :param messages: list with messages
    :return: integer
    """
    index = -1
    for message in reversed(messages):
        try:
            rrc = message.get("pdu").get("message").get("c1").get("rrcConnectionRequest")
            if rrc:
                index = messages.index(message)
                break
        except AttributeError:
            pass
    return index


