def extract_ip_addr_from_pdu_session_establishment_accept(message):
    """
    get_ip_addr_from_pdu_session_establishment_accept
    :param message: message dict
    :return: string
    """
    address_octet = 0
    ipv4 = list()

    while address_octet < 4:
        try:
            ip = message.get("pdu").get("nr5g_smm_msg").get("pdu_session_estab_accept").get("pdu_addr").\
                get("ipv4_addr[{}]".format(address_octet))
            pattern = r"(\d{1,3})"
            match = re.findall(pattern, ip)
            ipv4.append(match[0])
            address_octet += 1
        except AttributeError:
            return False
    return '.'.join(ipv4)


