def extract_cell_id_from_sib1_r13(message):
    """
    extract_cell_id_from_sib1_r13
    :param message: message dict
    :return string: cell_id
    """
    try:
        cell_id = message.get("pdu").get("message").get("c1").get("systemInformationBlockType1-r13").get(
            "cellAccessRelatedInfo-r13").get("cellIdentity-r13")
        cell_id = cell_id.replace('0b', '').replace(' ', '')
        cell_id = int(cell_id, base=2)
    except (AttributeError, TypeError):
        return None
    return cell_id


def find_index_of_last_pdu_session_establishment_accept_message(messages):
    """
    find_index_of_last_attach_accept_message
    :param messages: list with messages
    :return: integer
    """
    index = -1
    for message in reversed(messages):
        if is_pdu_session_establishment_accept(message):
            index = messages.index(message)
    return index


