def check_if_message_rrc_connection_setup_complete_contains_dedicated_info_nas(message):
    """
    check_if_message_rrc_connection_setup_complete_contains_dedicated_info_nas
    :param message: dict with message
    :return boolean
    """
    try:
        msg = message.get("pdu").get("message").get("c1").get("rrcConnectionSetupComplete") \
            .get("criticalExtensions").get("c1").get("rrcConnectionSetupComplete-r8") \
            .get("dedicatedInfoNAS")
    except AttributeError:
        return False
    return True if msg else False


def check_if_message_rrc_connection_setup_complete_r13_contains_dedicated_info_nas(message):
    """
    check_if_message_rrc_connection_setup_complete_r13_contains_dedicated_info_nas
    :param message: dict with message
    :return boolean
    """
    try:
        msg = message.get("pdu").get("message").get("c1").get("rrcConnectionSetupComplete-r13") \
            .get("criticalExtensions").get("rrcConnectionSetupComplete-r13").get("dedicatedInfoNAS-r13")
    except AttributeError:
        return False
    return True if msg else False


def return_all_key_values_of_iterable(iterable, key):
    """
    return_all_key_values_of_iterable
    :param iterable:    iterable
    :param key:         key
    :return list
    """
    all_values = []
    sub_elements = [iterable]
    while sub_elements:
        element = sub_elements.pop()
        if isinstance(element, list):
            sub_elements.extend(element)
        if isinstance(element, dict):
            _extract_value_from_dict(all_values, element, key, sub_elements)
    return all_values


def _extract_value_from_dict(all_values, element, key, sub_elements):
    for found_key, value in element.items():
        if found_key == key:
            all_values.append(value)
        if isinstance(value, list) or isinstance(value, dict):
            sub_elements.append(value)
